import{_ as o,o as r,c as l,ag as e}from"./chunks/framework.D64lb950.js";const d=JSON.parse('{"title":"值得反复阅读的几本好书","description":"","frontmatter":{"title":"值得反复阅读的几本好书","date":"2026-06-24T00:00:00.000Z","tags":["读书","成长","思维","推荐"],"category":"随笔","pinned":true},"headers":[],"relativePath":"posts/good-books-recommendation.md","filePath":"posts/good-books-recommendation.md","lastUpdated":1782269968000}'),n={name:"posts/good-books-recommendation.md"};function s(a,t,p,i,u,g){return r(),l("div",null,[...t[0]||(t[0]=[e('<h1 id="值得反复阅读的几本好书" tabindex="-1">值得反复阅读的几本好书 <a class="header-anchor" href="#值得反复阅读的几本好书" aria-label="Permalink to &quot;值得反复阅读的几本好书&quot;">​</a></h1><p>读书是成本最低的自我投资。一本书几十块钱，换来的却是作者几十年思考的结晶。这两年陆陆续续读了不少书，挑了 5 本真正改变我认知的，分享给你。</p><p>筛选标准很简单：<strong>读完不是&quot;知道了&quot;，而是&quot;不一样了&quot;</strong>。那些读完觉得有道理、但生活照旧的书，不在此列。</p><h2 id="_1-《高效能人士的七个习惯》——-不是时间管理-是人格成长地图" tabindex="-1">1.《高效能人士的七个习惯》—— 不是时间管理，是人格成长地图 <a class="header-anchor" href="#_1-《高效能人士的七个习惯》——-不是时间管理-是人格成长地图" aria-label="Permalink to &quot;1.《高效能人士的七个习惯》—— 不是时间管理，是人格成长地图&quot;">​</a></h2><blockquote><p>作者：史蒂芬·柯维 | 豆瓣 8.6 | 已售 4000 万册</p></blockquote><p>💡 <strong>核心洞见</strong></p><p>柯维把人的成长拆成三个阶段：<strong>依赖 → 独立 → 互赖</strong>。</p><p>大多数人一辈子卡在&quot;依赖&quot;阶段——等着别人给方向、给方案、给认可。七个习惯的本质不是让你&quot;效率更高&quot;，而是让你从内心先独立起来，再学会与他人协作。</p><p>书里最重要的一个概念是「<strong>关注圈 vs 影响圈</strong>」。你每天焦虑的事情，90% 都在关注圈里（你控制不了）；真正应该花精力的，是影响圈（你能直接改变的事）。<strong>把注意力从关注圈拉回影响圈，焦虑就少了一大半。</strong></p><p>🎯 <strong>现实应用</strong></p><ul><li>遇到问题时先问自己：&quot;这事我能控制什么？&quot;然后只做那一部分</li><li>「以终为始」这句话我贴在显示器上——先想清楚你要成为什么样的人，再倒推今天该做什么</li><li>把「要事第一」落到实处：每天开工前只定三件最重要的事，做完就算赢</li></ul><p>📌 <strong>一句话带走</strong></p><blockquote><p>&quot;播种一个思想，收获一个行动；播种一个行动，收获一个习惯；播种一个习惯，收获一个品格；播种一个品格，收获一个命运。&quot;</p></blockquote><hr><h2 id="_2-《穷查理宝典》——-一个-99-岁老人的智慧合集" tabindex="-1">2.《穷查理宝典》—— 一个 99 岁老人的智慧合集 <a class="header-anchor" href="#_2-《穷查理宝典》——-一个-99-岁老人的智慧合集" aria-label="Permalink to &quot;2.《穷查理宝典》—— 一个 99 岁老人的智慧合集&quot;">​</a></h2><blockquote><p>作者：查理·芒格 | 豆瓣 8.8 | 巴菲特搭档，伯克希尔副董事长</p></blockquote><p>💡 <strong>核心洞见</strong></p><p>芒格的核心思想就一个词：<strong>多元思维模型</strong>。</p><p>不要手里只拿一把锤子，看什么都像钉子。心理学、经济学、物理学、生物学、数学——每个学科里最重要的那两三个模型，拿过来用，你判断事情的准确率会大幅提升。</p><p>另一个冲击我的观点是「<strong>反过来想</strong>」。如果你想幸福，先研究什么会让人不幸然后避开；如果你想赚钱，先研究什么会让人破产然后不做。<strong>想不明白正面的时候，就从反面想，往往豁然开朗。</strong></p><p>🎯 <strong>现实应用</strong></p><ul><li>做重要决定前列「不可为清单」：哪些事绝对不能做？比「该做什么」更有用</li><li>遇到认知以外的领域，不急着下判断，先去学最基础的那个模型</li><li>承认自己不懂的能力，比假装懂的能力值钱一万倍——芒格一辈子都在说「我不知道」</li></ul><p>📌 <strong>一句话带走</strong></p><blockquote><p>&quot;我这辈子遇到的聪明人，没有一个不每天阅读的——没有，一个都没有。&quot;</p></blockquote><hr><h2 id="_3-《思考-快与慢》——-你的大脑一直在骗你" tabindex="-1">3.《思考，快与慢》—— 你的大脑一直在骗你 <a class="header-anchor" href="#_3-《思考-快与慢》——-你的大脑一直在骗你" aria-label="Permalink to &quot;3.《思考，快与慢》—— 你的大脑一直在骗你&quot;">​</a></h2><blockquote><p>作者：丹尼尔·卡尼曼 | 豆瓣 8.2 | 诺贝尔经济学奖得主</p></blockquote><p>💡 <strong>核心洞见</strong></p><p>卡尼曼把大脑分成两套系统：</p><table tabindex="0"><thead><tr><th style="text-align:left;">系统 1（快）</th><th style="text-align:left;">系统 2（慢）</th></tr></thead><tbody><tr><td style="text-align:left;">直觉、自动</td><td style="text-align:left;">理性、费力</td></tr><tr><td style="text-align:left;">不耗能量</td><td style="text-align:left;">消耗大量能量</td></tr><tr><td style="text-align:left;">容易出错</td><td style="text-align:left;">相对准确</td></tr><tr><td style="text-align:left;">24 小时在线</td><td style="text-align:left;">能用就偷懒</td></tr></tbody></table><p>大部分时候，是系统 1 在替你决策——你以为是自己在思考，其实是大脑在走捷径。</p><p>书里列出几十种认知偏差，最有杀伤力的是「<strong>可得性偏差</strong>」：你会高估最近看到、听到的事情的重要性。飞机失事新闻看多了就觉得飞机不安全，实际上飞机比汽车安全得多。<strong>你的判断不基于事实，基于你最近看到了什么。</strong></p><p>🎯 <strong>现实应用</strong></p><ul><li>做重要决策时，故意放慢一步，给自己 24 小时冷却期</li><li>听到任何新闻时先想：&quot;我是不是因为最近老看到它，才觉得它重要？&quot;</li><li>承认「我不像自己以为的那么理性」，这本身就是一种理性</li></ul><p>📌 <strong>一句话带走</strong></p><blockquote><p>&quot;我们对自己认为知道的，往往过于自信；对自己不知道的，却一无所知。&quot;</p></blockquote><hr><h2 id="_4-《非暴力沟通》——-90-的矛盾来自不会说话" tabindex="-1">4.《非暴力沟通》—— 90% 的矛盾来自不会说话 <a class="header-anchor" href="#_4-《非暴力沟通》——-90-的矛盾来自不会说话" aria-label="Permalink to &quot;4.《非暴力沟通》—— 90% 的矛盾来自不会说话&quot;">​</a></h2><blockquote><p>作者：马歇尔·卢森堡 | 豆瓣 8.6 | 全球冲突调解经典</p></blockquote><p>💡 <strong>核心洞见</strong></p><p>这本书给了我一套全新的沟通公式：<strong>观察 + 感受 + 需要 + 请求</strong>。</p><p>大多数人的沟通模式是：「你总是……」「你从来不……」「你怎么又……」。这在对方听来全是评判和攻击，对方第一反应不是理解你，而是防御或反击。</p><p>非暴力沟通做四步拆解：</p><ol><li><strong>观察</strong>：说事实，不加评判（&quot;你这周迟到了三次&quot; vs &quot;你这个人不靠谱&quot;）</li><li><strong>感受</strong>：说出自己的真实情绪（&quot;我有些担心&quot; 不是 &quot;我很生气&quot;）</li><li><strong>需要</strong>：说出背后的需求（&quot;因为我希望团队能互相支持&quot;）</li><li><strong>请求</strong>：提出具体的行动请求（&quot;下次能提前跟我说一声吗？&quot;）</li></ol><p><strong>同样的诉求，换一种表达，结局完全不同。</strong></p><p>🎯 <strong>现实应用</strong></p><ul><li>想发火之前，先问自己：&quot;我真正的需求是什么？&quot;说出来，而不是骂出来</li><li>听别人抱怨时，不急着给建议，先帮对方把感受和需要理清楚</li><li>把「你从来不听我说」改成「我希望你能听我把话说完」，效果天差地别</li></ul><p>📌 <strong>一句话带走</strong></p><blockquote><p>&quot;当你听到对方说&#39;不&#39;的时候，问问自己：这个&#39;不&#39;背后，是对方的什么需要没有被满足？&quot;</p></blockquote><hr><h2 id="_5-《刻意练习》——-天才不是天生的" tabindex="-1">5.《刻意练习》—— 天才不是天生的 <a class="header-anchor" href="#_5-《刻意练习》——-天才不是天生的" aria-label="Permalink to &quot;5.《刻意练习》—— 天才不是天生的&quot;">​</a></h2><blockquote><p>作者：安德斯·艾利克森 | 豆瓣 8.0 | 推翻&quot;一万小时定律&quot;的书</p></blockquote><p>💡 <strong>核心洞见</strong></p><p>一万小时定律是错的。真正让人变厉害的，不是时间长短，是 <strong>练习的质量</strong>。</p><p>艾利克森提出「刻意练习」的四个标准：</p><ul><li><strong>有明确目标</strong>：不是&quot;练一小时琴&quot;，是&quot;把这段弹到不出错&quot;</li><li><strong>极度专注</strong>：练习时脑子是紧绷的，不舒服的</li><li><strong>即时反馈</strong>：知道哪里做对了、哪里做错了</li><li><strong>走出舒适区</strong>：一直在做刚好做不好的事</li></ul><p>一万小时的流水线工作不会让你成为专家，一万小时带着脑子、有反馈、持续突破边界的练习才会。<strong>时间只是入场券，方法是决定因素。</strong></p><p>🎯 <strong>现实应用</strong></p><ul><li>学习新技术时，不再漫无目的地&quot;多练&quot;，而是拆解出具体要攻克的小目标</li><li>主动找反馈——问同事&quot;我这次代码哪里写得不够好&quot;，而不是等出了问题再改</li><li>意识到&quot;我已经做了三年&quot;不说明任何问题——三年里有没有刻意提升才是关键</li></ul><p>📌 <strong>一句话带走</strong></p><blockquote><p>&quot;如果你觉得某件事很轻松，那你大概率没有在进步。&quot;</p></blockquote><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><p>之前写过两篇更详细的读书笔记，感兴趣的可以深入看看：</p><ul><li><a href="/my-blog/posts/rich-dad-poor-dad-review">《穷爸爸富爸爸》读书笔记</a> —— 资产和负债的区分，是改变财务认知的第一步</li><li><a href="/my-blog/posts/zero-to-one-review">《从0到1》读书笔记</a> —— 竞争是失败者的游戏，创新才是真正的壁垒</li></ul><hr><h2 id="选书和读书的几个小建议" tabindex="-1">选书和读书的几个小建议 <a class="header-anchor" href="#选书和读书的几个小建议" aria-label="Permalink to &quot;选书和读书的几个小建议&quot;">​</a></h2><p><strong>怎么挑书？</strong> 先看目录，再看引言，然后翻一章最感兴趣的。如果一章都读不下去，果断放下。世界上好书太多，不值得在不合适的书上纠结。</p><p><strong>读透一本 &gt; 翻过十本。</strong> 好消息是这五本互相有交叉——芒格受柯维的影响，卡尼曼的研究也解释了为什么非暴力沟通有效。反复读，把体系串起来，比散读一百本有用得多。</p><p><strong>读完一定要写。</strong> 哪怕只写三句话：这本书讲了什么？改变了我的什么认知？我接下来打算怎么做？写不出来就是没读懂。</p><hr><p>这五本书刚好构成一个成长闭环：<strong>先修炼自己（高效能）→ 构建思维框架（穷查理）→ 认清认知局限（思考快与慢）→ 改善人际关系（非暴力沟通）→ 掌握学习方法（刻意练习）。</strong></p><p>你心中最好的一本书是什么？欢迎留言告诉我。</p>',73)])])}const h=o(n,[["render",s]]);export{d as __pageData,h as default};
